mapper.select:
select count(*) from pcr_result_vw


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}


		and category =#{category}


		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


		and tested_date between #{tested_date_B} And #{tested_date_N} 


		and sample_id in

			#{item}




		and sample_id = #{sample_id}

select result_id, report_id, sample_id,barcode,subbarcode, disease_type,category,
pcr_variant_id,gene_symbol, variant,variant_frequency,tested_date,tested_by,checked_date,
checked_by,report_date from pcr_result_vw


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}


		and category =#{category}


		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


		and tested_date between #{tested_date_B} And #{tested_date_N} 


		and sample_id in

			#{item}




		and sample_id = #{sample_id}


limit #{pageNo},#{pageSize}

select specimen_type name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by specimen_type order by count(distinct subbarcode) desc

select category name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by category order by count(distinct subbarcode) desc

select cancertype name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by cancertype order by count(distinct subbarcode) desc

select clinicalremark name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by clinicalremark order by count(distinct subbarcode) desc

select pathologicaltype name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by pathologicaltype order by count(distinct subbarcode) desc

		select round(variant_frequency,1) as name, count(distinct subbarcode) data FROM omics.pcr_result_vw  

			variant_frequency < 0.95

				and category =#{category}


				and gene_symbol =#{gene_symbol}


				and variant =#{variant}

				and tested_date between #{tested_date_B} and #{tested_date_E} 

				and variant_frequency >= #{variant_frequency_sta}


				and variant_frequency  <= #{variant_frequency_end}


		group by round(variant_frequency,1) 
		union
	    select round(variant_frequency,0) as name, count(distinct subbarcode) data FROM omics.pcr_result_vw  

	    	variant_frequency >= 0.95 and variant_frequency < 9.5

				and category =#{category}


				and gene_symbol =#{gene_symbol}


				and variant =#{variant}

				and tested_date between #{tested_date_B} and #{tested_date_E} 

				and variant_frequency >= #{variant_frequency_sta}


				and variant_frequency  <= #{variant_frequency_end}


	    group by round(variant_frequency,0)	
	    union
	    select round(variant_frequency,-1) as name, count(distinct subbarcode) data FROM omics.pcr_result_vw 

	         variant_frequency >= 9.5 

				and category =#{category}


				and gene_symbol =#{gene_symbol}


				and variant =#{variant}

				and tested_date between #{tested_date_B} and #{tested_date_E} 

				and variant_frequency >= #{variant_frequency_sta}


				and variant_frequency  <= #{variant_frequency_end}


 		group by round(variant_frequency,-1) 
 		order by name

select gene_symbol name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by gene_symbol order by count(distinct subbarcode) desc

select concat(gene_symbol, ' ', variant) name, count(distinct subbarcode) data FROM pcr_result_vw


		and category =#{category}


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}

		and tested_date between #{tested_date_B} and #{tested_date_E} 

		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


group by concat(gene_symbol, ' ', variant) order by count(distinct subbarcode) desc

select received_date, subbarcode, person_name,specimen_type,category, cancertype,pathologicaltype,
clinicalstages,libraryname, sales_contact,hospital,locationname,doctorname,report_date,
variant,variant_frequency from pcr_result_vw


		and gene_symbol =#{gene_symbol}


		and variant =#{variant}


		and category =#{category}


		and variant_frequency >= #{variant_frequency_sta}


		and variant_frequency  <= #{variant_frequency_end}


		and tested_date between #{tested_date_B} And #{tested_date_N}
